//! Unified agentic loop engine.//!//! Provides a single implementation of the core LLM call → tool execution →//! result processing → context update → repeat cycle. Three consumers//! (chat dispatcher, job worker, container runtime) customize behavior//! via the `LoopDelegate` trait.use async_trait::async_trait;use crate::agent::session::PendingApproval;use crate::error::Error;use crate::llm::{ChatMessage, Reasoning, ReasoningContext, RespondResult};/// Signal from the delegate indicating how the loop should proceed.pub enum LoopSignal {    /// Continue normally.    Continue,    /// Stop the loop gracefully.    Stop,    /// Inject a user message into context and continue.    InjectMessage(String),}/// Outcome of a text response from the LLM.pub enum TextAction {    /// Return this as the final loop result.    Return(LoopOutcome),    /// Continue the loop (text was handled but loop should proceed).    Continue,}/// Final outcome of the agentic loop.pub enum LoopOutcome {    /// Completed with a text response.    Response(String),    /// Loop was stopped by a signal.    Stopped,    /// Max iterations exceeded.    MaxIterations,    /// A tool requires user approval before continuing (chat delegate only).    NeedApproval(Box<PendingApproval>),}/// Configuration for the agentic loop.pub struct AgenticLoopConfig {    pub max_iterations: usize,    pub enable_tool_intent_nudge: bool,    pub max_tool_intent_nudges: u32,}impl Default for AgenticLoopConfig {    fn default() -> Self {        Self {            max_iterations: 50,            enable_tool_intent_nudge: true,            max_tool_intent_nudges: 2,        }    }}/// Strategy trait — each consumer implements this to customize I/O and lifecycle.////// The shared loop calls these methods at well-defined points. Consumers/// implement only the behavior that differs between chat, job, and container/// contexts. The loop itself handles the common logic: tool intent nudge,/// iteration counting, tool definition refresh, and the respond → execute → process cycle.////// # `Send + Sync` requirement////// This trait requires `Send + Sync` because the loop accepts `&dyn LoopDelegate`./// Delegates using borrowed references (e.g. `ChatDelegate<'a>`) must ensure all/// borrowed fields are `Send + Sync`. This is a load-bearing constraint: if a/// delegate needs to be spawned into a detached task, it must use `Arc`-based/// ownership instead of borrows (as `JobDelegate` and `ContainerDelegate` do).#[async_trait]pub trait LoopDelegate: Send + Sync {    /// Called at the start of each iteration. Check for external signals    /// (cancellation, user messages, stop requests).    async fn check_signals(&self) -> LoopSignal;    /// Called before the LLM call. Allows the delegate to refresh tool    /// definitions, enforce cost guards, or inject messages.    /// Return `Some(outcome)` to break the loop early.    async fn before_llm_call(        &self,        reason_ctx: &mut ReasoningContext,        iteration: usize,    ) -> Option<LoopOutcome>;    /// Call the LLM and return the result. Delegates own the LLM call    /// to handle consumer-specific concerns (rate limiting, auto-compaction,    /// cost tracking, force_text mode).    async fn call_llm(        &self,        reasoning: &Reasoning,        reason_ctx: &mut ReasoningContext,        iteration: usize,    ) -> Result<crate::llm::RespondOutput, Error>;    /// Handle a text-only response from the LLM.    /// Return `TextAction::Return` to exit the loop, `TextAction::Continue` to proceed.    async fn handle_text_response(        &self,        text: &str,        reason_ctx: &mut ReasoningContext,    ) -> TextAction;    /// Execute tool calls and add results to context.    /// Return `Some(outcome)` to break the loop (e.g. approval needed).    async fn execute_tool_calls(        &self,        tool_calls: Vec<crate::llm::ToolCall>,        content: Option<String>,        reason_ctx: &mut ReasoningContext,    ) -> Result<Option<LoopOutcome>, Error>;    /// Called when the LLM expresses tool intent without actually calling a tool.    /// Delegates can use this to emit events or log the nudge for observability.    async fn on_tool_intent_nudge(&self, _text: &str, _reason_ctx: &mut ReasoningContext) {}    /// Called after each successful iteration (no error, no early return).    async fn after_iteration(&self, _iteration: usize) {}}/// Run the unified agentic loop.////// This is the single implementation used by all three consumers (chat, job, container)./// The `delegate` provides consumer-specific behavior via the `LoopDelegate` trait.